function isEventLike(canonical) {
  if (canonical == null) { return false; }
  return canonical.startsWith('lifecycle.') || canonical.startsWith('fota.') || canonical.startsWith('ota.') || canonical.startsWith('control.');
}
var transitions = msg['ev'];
if (transitions == null || transitions.size() == 0) {
  return {msg: msg, metadata: metadata, msgType: 'IGNORE'};
}
var picked = null;
for (t : transitions) {
  var code = '' + t['c'];
  var canonical = alarmMap[code];
  if (canonical != null && isEventLike(canonical)) {
    picked = {'transition': t, 'canonicalEvent': canonical, 'sourceCode': code};
  }
}
if (picked == null) {
  return {msg: msg, metadata: metadata, msgType: 'IGNORE'};
}
var candidateType = 'lifecycle';
if (picked['canonicalEvent'].startsWith('fota.') || picked['canonicalEvent'].startsWith('ota.')) {
  candidateType = 'ota';
}
var stateCode = picked['transition']['s'];
var lifecycleState = 'RAISED';
if (stateCode == 0) {
  lifecycleState = 'CLEARED';
} else if (stateCode == 2) {
  lifecycleState = 'UPDATED';
}
var sourceEventTs = picked['transition']['ts'];
if (sourceEventTs == null) { sourceEventTs = msg['sourceEventTs']; }
if (sourceEventTs == null) { sourceEventTs = msg['ts']; }
if (sourceEventTs == null) { sourceEventTs = metadata['ts']; }
return {msg: {'candidateType': candidateType, 'canonicalEvent': picked['canonicalEvent'], 'sourceCode': picked['sourceCode'], 'transitionState': lifecycleState, 'sourceEventTs': sourceEventTs}, metadata: metadata, msgType: 'Success'};

